style.css:
@-moz-document domain("youtube.com") {
body, #container, ytd-app {
    background-image: url("https://i.imgur.com/XTOzB6O.png");
    background-size: cover;
    background-attachment: fixed;
    background-repeat: no-repeat;
    background-position: center;
    color: #4a1c40 !important;
    font-family: 'Courier New', Courier, monospace !important;
  }

  .ytd-rich-grid-renderer, ytd-video-renderer, .style-scope.ytd-item-section-renderer {
    background-color: rgba(255, 240, 245, 0.9) !important;
    border-radius: 16px !important;
    border: 1px solid #f9a8d4 !important;
    padding: 10px !important;
  }

  a:hover, button:hover {
    color: gold !important;
    text-shadow: 0 0 8px pink;
    transition: all 0.3s ease-in-out;
  }

  #masthead {
    background: linear-gradient(to right, #f8bbd0, #f48fb1) !important;
    border-bottom: 2px solid gold !important;
  }

  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #ffeef8;
  }
  ::-webkit-scrollbar-thumb {
    background-color: gold;
    border-radius: 10px;
    border: 2px solid pink;
  }

  button, .yt-simple-endpoint, a {
    color: #c71585 !important;
    font-weight: bold;
  }
}
